function icon(string $name): string {
    $paths=['overview'=>'<rect x="3" y="3" width="7" height="7"/><rect x="14" y="3" width="7" height="7"/><rect x="3" y="14" width="7" height="7"/><rect x="14" y="14" width="7" height="7"/>','routes'=>'<path d="M5 5h.01M5 19h.01M19 12h.01M5 5v8a6 6 0 0 0 6 6h-6M5 5h8a6 6 0 0 1 6 6v1"/>','schedule'=>'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M16 3v4M8 3v4M3 11h18"/>','events'=>'<path d="M12 8v4l3 3"/><circle cx="12" cy="12" r="9"/>','scenarios'=>'<path d="M8 5v14l11-7z"/>','settings'=>'<circle cx="12" cy="12" r="3"/><path d="M19.4 15a1.7 1.7 0 0 0 .3 1.9l.1.1-2.8 2.8-.1-.1a1.7 1.7 0 0 0-1.9-.3 1.7 1.7 0 0 0-1 1.6v.2h-4V21a1.7 1.7 0 0 0-1-1.6 1.7 1.7 0 0 0-1.9.3l-.1.1L4.2 17l.1-.1a1.7 1.7 0 0 0 .3-1.9A1.7 1.7 0 0 0 3 14H2.8v-4H3a1.7 1.7 0 0 0 1.6-1 1.7 1.7 0 0 0-.3-1.9L4.2 7 7 4.2l.1.1A1.7 1.7 0 0 0 9 4.6a1.7 1.7 0 0 0 1-1.6v-.2h4V3a1.7 1.7 0 0 0 1 1.6 1.7 1.7 0 0 0 1.9-.3l.1-.1L19.8 7l-.1.1a1.7 1.7 0 0 0-.3 1.9 1.7 1.7 0 0 0 1.6 1h.2v4H21a1.7 1.7 0 0 0-1.6 1z"/>','about'=>'<circle cx="12" cy="12" r="9"/><path d="M12 11v5M12 8h.01"/>'];
    return '<svg viewBox="0 0 24 24" aria-hidden="true">'.($paths[$name]??$paths['about']).'</svg>';
}
function badge(string $status, ?string $attention=null): string {
    if($attention==='overdue') return '<span class="badge-status s-overdue">Срок нарушен</span>';
    if($attention && $status!=='completed') return '<span class="badge-status s-attention">Требует внимания</span>';
    return '<span class="badge-status s-'.rg_e($status).'">'.rg_e(rg_status_label($status)).'</span>';
}
